[{"order":1,"type":"heading","text":"Binary Search Trees (BST): Insertion, Deletion, Search"},{"order":2,"type":"paragraph","text":"A Binary Search Tree (BST) is a node-based binary tree data structure which has the following properties: The left subtree of a node contains only nodes with keys less than the node's key. The right subtree of a node contains only nodes with keys greater than the node's key. Both the left and right subtrees must also be binary search trees. There must be no duplicate nodes."},{"order":3,"type":"subheading","text":"Insertion"},{"order":4,"type":"paragraph","text":"Inserting a new node into a BST involves finding the correct position for the new node while maintaining the BST properties. We start at the root and traverse down the tree. At each node, we compare the key of the new node with the key of the current node. If the new node's key is less than the current node's key, we move to the left subtree. If it's greater, we move to the right subtree. We continue until we reach a null node, which is where we insert the new node."},{"order":5,"type":"code","text":"function insertNode(root, key) {
  if (root === null) {
    return { key: key, left: null, right: null };
  }

  if (key < root.key) {
    root.left = insertNode(root.left, key);
  } else if (key > root.key) {
    root.right = insertNode(root.right, key);
  }

  return root;
}"},{"order":6,"type":"subheading","text":"Deletion"},{"order":7,"type":"paragraph","text":"Deleting a node from a BST is more complex than insertion. There are three possible cases:
1.  The node to be deleted is a leaf node.
2.  The node to be deleted has only one child.
3.  The node to be deleted has two children."},{"order":8,"type":"bullet_point","text":"Leaf Node: Simply remove the node."},{"order":9,"type":"bullet_point","text":"Node with One Child: Replace the node with its child."},{"order":10,"type":"bullet_point","text":"Node with Two Children: Find the inorder successor (smallest node in the right subtree) or inorder predecessor (largest node in the left subtree), replace the node with the successor/predecessor, and then delete the successor/predecessor (which will be in one of the first two cases)."},{"order":11,"type":"code","text":"function deleteNode(root, key) {
  if (root === null) {
    return null;
  }

  if (key < root.key) {
    root.left = deleteNode(root.left, key);
  } else if (key > root.key) {
    root.right = deleteNode(root.right, key);
  } else {
    // Node with only one child or no child
    if (root.left === null) {
      return root.right;
    } else if (root.right === null) {
      return root.left;
    }

    // Node with two children: Get the inorder successor (smallest
    // in the right subtree)
    root.key = minValue(root.right);

    // Delete the inorder successor
    root.right = deleteNode(root.right, root.key);
  }

  return root;
}

function minValue(node) {
  let minv = node.key;
  while (node.left != null) {
    minv = node.left.key;
    node = node.left;
  }
  return minv;
}"},{"order":12,"type":"subheading","text":"Search"},{"order":13,"type":"paragraph","text":"Searching for a node with a specific key in a BST is efficient due to the ordered nature of the tree. We start at the root and compare the key we're searching for with the key of the current node. If the keys match, we've found the node. If the search key is less than the current node's key, we move to the left subtree. If it's greater, we move to the right subtree. We continue until we find the node or reach a null node (meaning the key is not in the tree)."},{"order":14,"type":"code","text":"function searchNode(root, key) {
  if (root === null || root.key === key) {
    return root;
  }

  if (key < root.key) {
    return searchNode(root.left, key);
  }

  return searchNode(root.right, key);
}"}]
